private static MimeType parseMimeTypeInternal(String mimeType) {
    int index = mimeType.indexOf(';');
    String fullType = (index >= 0 ? mimeType.substring(0, index) : mimeType).trim();
    if (fullType.isEmpty()) {
        throw new InvalidMimeTypeException(mimeType, "'mimeType' must not be empty");
    }

    // java.net.HttpURLConnection returns a *; q=.2 Accept header
    if (MimeType.WILDCARD_TYPE.equals(fullType)) {
        fullType = "*/*";
    }
    int subIndex = fullType.indexOf('/');
    if (subIndex == -1) {
        throw new InvalidMimeTypeException(mimeType, "does not contain '/'");
    }
    if (subIndex == fullType.length() - 1) {
        throw new InvalidMimeTypeException(mimeType, "does not contain subtype after '/'");
    }
    String type = fullType.substring(0, subIndex);
    String subtype = fullType.substring(subIndex + 1);
    if (MimeType.WILDCARD_TYPE.equals(type) && !MimeType.WILDCARD_TYPE.equals(subtype)) {
        throw new InvalidMimeTypeException(mimeType, "wildcard type is legal only in '*/*' (all mime types)");
    }

    Map<String, String> parameters = null;
    do {
        int nextIndex = index + 1;
        boolean quoted = false;
        while (nextIndex < mimeType.length()) {
            char ch = mimeType.charAt(nextIndex);
            if (ch == ';') {
                if (!quoted) {
                    break;
                }
            }
            else if (ch == '"' && mimeType.charAt(nextIndex - 1) != '\\') {
                quoted = !quoted;
            }
            nextIndex++;
        }
        String parameter = mimeType.substring(index + 1, nextIndex).trim();
        if (parameter.length() > 0) {
            if (parameters == null) {
                parameters = new LinkedHashMap<>(4);
            }
            int eqIndex = parameter.indexOf('=');
            if (eqIndex >= 0) {
                String attribute = parameter.substring(0, eqIndex).trim();
                String value = parameter.substring(eqIndex + 1).trim();
                parameters.put(attribute, value);
            }
        }
        index = nextIndex;
    }
    while (index < mimeType.length());

    try {
        return new MimeType(type, subtype, parameters);
    }
    catch (UnsupportedCharsetException ex) {
        throw new InvalidMimeTypeException(mimeType, "unsupported charset '" + ex.getCharsetName() + "'");
    }
    catch (IllegalArgumentException ex) {
        throw new InvalidMimeTypeException(mimeType, ex.getMessage());
    }
}

public static Locale parseLocaleString(String localeString) {
    String[] parts = tokenizeToStringArray(localeString, "_ ", false, false);
    String language = (parts.length > 0 ? parts[0] : "");
    String country = (parts.length > 1 ? parts[1] : "");
    validateLocalePart(language);
    validateLocalePart(country);
    String variant = "";
    if (parts.length >= 2) {
        // There is definitely a variant, and it is everything after the country
        // code sans the separator between the country code and the variant.
        int endIndexOfCountryCode = localeString.lastIndexOf(country) + country.length();
        // Strip off any leading '_' and whitespace, what's left is the variant.
        variant = trimLeadingWhitespace(localeString.substring(endIndexOfCountryCode));
        if (variant.startsWith("_")) {
            variant = trimLeadingCharacter(variant, '_');
        }
    }
    return (language.length() > 0 ? new Locale(language, country, variant) : null);
}

private String substringWithTrimmedWhitespaceAndQuotesIfQuotesPresent(char chars[], int offset, int count) {
    int start = offset;
    int len = count;

    while ((start < (start + len)) && (chars[start] <= ' ')) {
        start++;
        len--;
    }

    while ((start < (start + len)) && ((start + len - 1 < chars.length) && (chars[start + len - 1] <= ' '))) {
        len--;
    }

    String value;

    if ((chars.length > 2) && (chars[start] == quoteCharacter) && (chars[start + len - 1] == quoteCharacter)) {
        value = new String(chars, start + 1, len - 2);
        if (value.contains(escapedQuoteString)) {
            value = StringUtils.replace(value, escapedQuoteString, quoteString);
        }
    }
    else {
        value = new String(chars, offset, count);
    }

    return value;
}

public class SyslogToMapTransformer extends AbstractPayloadTransformer<Object, Map<String, ?>> {
    private final SimpleDateFormat dateFormat = new SimpleDateFormat("MMM dd HH:mm:ss");

    private Map<String, ?> transform(String payload) {
        Map<String, Object> map = new LinkedHashMap<String, Object>();
        Matcher matcher = pattern.matcher(payload);
        if (matcher.matches()) {
            try {
                String facilityString = matcher.group(1);
                int facility = Integer.parseInt(facilityString);
                int severity = facility & 0x7;
                facility = facility >> 3;
                map.put(FACILITY, facility);
                map.put(SEVERITY, severity);
                String timestamp = matcher.group(2);
                Date date;
                try {
                    date = this.dateFormat.parse(timestamp);
                    Calendar calendar = Calendar.getInstance();
                    int year = calendar.get(Calendar.YEAR);
                    int month = calendar.get(Calendar.MONTH);
                    calendar.setTime(date);
                    /*
                     * syslog date doesn't include a year so we
                     * need to insert the current year - adjusted
                     * if necessary if close to midnight on Dec 31.
                     */
                    if (month == 11 && calendar.get(Calendar.MONTH) == 0) {
                        calendar.set(Calendar.YEAR, year + 1);
                    }
                    else if (month == 0 && calendar.get(Calendar.MONTH) == 1) {
                        calendar.set(Calendar.YEAR, year - 1);
                    }
                    else {
                        calendar.set(Calendar.YEAR, year);
                    }
                    map.put(TIMESTAMP, calendar.getTime());
                }
                catch (Exception e) {
                    /*
                     * If we can't parse the timestamp, return it as an
                     * unmodified String. (Postel's law).
                     */
                    map.put(TIMESTAMP, timestamp);
                }
                map.put(HOST, matcher.group(3));
                if (StringUtils.hasLength(matcher.group(4))) {
                    map.put(TAG, matcher.group(4));
                }
                map.put(MESSAGE, matcher.group(5));
            }
            catch (Exception e) {
                if (logger.isDebugEnabled()) {
                    logger.debug("Could not decode:" + payload, e);
                }
                map.clear();
                map.put(UNDECODED, payload);
            }
        }
        else {
            if (logger.isDebugEnabled()) {
                logger.debug("Could not decode:" + payload);
            }
            map.put(UNDECODED, payload);
        }
        return map;
    }
}

private void buildRolesReachableInOneOrMoreStepsMap() {
    this.rolesReachableInOneOrMoreStepsMap = new HashMap<>();
    // iterate over all higher roles from rolesReachableInOneStepMap

    for (GrantedAuthority role : this.rolesReachableInOneStepMap.keySet()) {
        Set<GrantedAuthority> rolesToVisitSet = new HashSet<>();

        if (this.rolesReachableInOneStepMap.containsKey(role)) {
            rolesToVisitSet.addAll(this.rolesReachableInOneStepMap.get(role));
        }

        Set<GrantedAuthority> visitedRolesSet = new HashSet<>();

        while (!rolesToVisitSet.isEmpty()) {
            // take a role from the rolesToVisit set
            GrantedAuthority aRole = rolesToVisitSet.iterator().next();
            rolesToVisitSet.remove(aRole);
            visitedRolesSet.add(aRole);
            if (this.rolesReachableInOneStepMap.containsKey(aRole)) {
                Set<GrantedAuthority> newReachableRoles = this.rolesReachableInOneStepMap
                        .get(aRole);

                // definition of a cycle: you can reach the role you are starting from
                if (rolesToVisitSet.contains(role)
                        || visitedRolesSet.contains(role)) {
                    throw new CycleInRoleHierarchyException();
                }
                else {
                    // no cycle
                    rolesToVisitSet.addAll(newReachableRoles);
                }
            }
        }
        this.rolesReachableInOneOrMoreStepsMap.put(role, visitedRolesSet);

        logger.debug("buildRolesReachableInOneOrMoreStepsMap() - From role " + role
                + " one can reach " + visitedRolesSet + " in one or more steps.");
    }

}

